public int[] whatFlavors(int[] cost, int money) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < cost.length; i++) {
        int need = money - cost[i];
        if (seen.containsKey(need)) {
            return new int[]{seen.get(need) + 1, i + 1};
        }
        seen.put(cost[i], i);
    }
    return new int[]{};
}

