def what_flavors(cost: list[int], money: int) -> list[int]:
    seen: dict[int, int] = {}
    for i, c in enumerate(cost):
        need = money - c
        if need in seen:
            return [seen[need] + 1, i + 1]
        seen[c] = i
    return []

